solution.solution.py:
import functools


def retry(times, exceptions=(Exception,)):
    if times < 1:
        raise ValueError("times must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == times:
                        raise
        return wrapper
    return decorator

unitTests:
@test("succeeds after failures")
def _():
    attempts = []
    @retry(times=3, exceptions=(ConnectionError,))
    def fetch():
        attempts.append(1)
        if len(attempts) < 3:
            raise ConnectionError("try again")
        return "data"
    check_eq(fetch(), "data")
    check_eq(len(attempts), 3)

@test("gives up after the last try")
def _():
    attempts = []
    @retry(times=2, exceptions=(ConnectionError,))
    def always_fails():
        attempts.append(1)
        raise ConnectionError("down")
    check_raises(ConnectionError, always_fails)
    check_eq(len(attempts), 2)

@test("other exceptions are not retried")
def _():
    attempts = []
    @retry(times=5, exceptions=(ConnectionError,))
    def bad():
        attempts.append(1)
        raise KeyError("x")
    check_raises(KeyError, bad)
    check_eq(len(attempts), 1)

@test("arguments, result and name")
def _():
    @retry(times=1)
    def add(a, b=10):
        return a + b
    check_eq(add(1, b=2), 3)
    check_eq(add.__name__, "add")

@test("times below 1 is refused")
def _():
    check_raises(ValueError, retry, 0)

